// D-05: the dashboard already computes this. This pushes it to the phone
// instead of waiting for somebody to notice it.
const cfg = $('Config').first().json;
const users = $('Get Users').all().map(u => u.json);
const findUser = (name) => {
  const k = String(name || '').trim().toLowerCase();
  if (!k) return null;
  return users.find(u => String(u.full_name || '').toLowerCase() === k ||
                         String(u.username || '').toLowerCase() === k) || null;
};

const byAgent = {};
for (const it of $input.all()) {
  const r = it.json;
  const key = r.agent_name || '(unassigned)';
  (byAgent[key] = byAgent[key] || []).push(r);
}

const out = [];
for (const [agent, rows] of Object.entries(byAgent)) {
  const u = findUser(agent);
  const overdue = rows.filter(r => Number(r.days_until) < 0);
  const today   = rows.filter(r => Number(r.days_until) === 0);
  const soon    = rows.filter(r => Number(r.days_until) > 0);
  const fmt = (list) => list.map(r =>
      `  - ${r.who} - ${r.what} (${r.doc_no}, due ${r.due_date})\n    ${cfg.portal_url}/record/${r.form_code}/${r.id}`
    ).join('\n');

  const body =
`Good morning${u && u.full_name ? ' ' + u.full_name.split(' ')[0] : ''}.

${overdue.length} overdue, ${today.length} due today, ${soon.length} due this week.
` +
(overdue.length ? `\nOVERDUE\n${fmt(overdue)}\n` : '') +
(today.length   ? `\nTODAY\n${fmt(today)}\n`     : '') +
(soon.length    ? `\nTHIS WEEK\n${fmt(soon)}\n`  : '') +
`\nLog the outcome against the record as you go - anything you log clears
itself from tomorrow's list.`;

  out.push({ json: {
    channel: 'email,whatsapp',
    to_email: u ? u.email : cfg.sales_manager_email,
    to_phone: '',
    subject: `[DHARANI 360] Your day: ${overdue.length + today.length} to clear`,
    message: body,
  }});
}
return out;
